 // D28: capa didáctica. Contexto, preguntas, pistas y criterios por actividad.
 const info=[
 {why:"Antes de tocar un equipo se define qué trabajo se hará, quién lo hará y en qué estado está el equipo. El permiso de trabajo deja constancia y avisa a operación.",risk:"Sin permiso, la planta puede arrancar o quedar fuera de servicio sin que nadie lo sepa, con personas dentro del equipo.",crit:"Red normal, grupo detenido y frío, personal con equipo de protección, herramientas definidas y operación informada.",learn:"El mantenimiento seguro empieza en el papel: estado del equipo, alcance, responsables y aviso a operación.",obj:"Registrar el permiso de trabajo en el gabinete de control.",hints:["El permiso se registra en el gabinete de control, en el extremo del generador.","Selecciona la Carpeta en la bolsa y pulsa el punto del control."]},
 {why:"En automático, el grupo arranca solo cuando falla la red. Poner el selector en fuera de servicio y colocar candado con etiqueta evita que alguien lo restablezca mientras se trabaja: es el principio de bloqueo y etiquetado.",risk:"Un arranque inesperado pone en movimiento ventilador, bandas y eje, y energiza el alternador con personas dentro del equipo.",crit:"Selector en fuera de servicio, candado personal colocado y etiqueta visible con responsable y fecha.",learn:"Apagar no es bloquear: el candado personal y la etiqueta impiden que otra persona restablezca el equipo por error.",obj:"Dejar el control del grupo bloqueado en fuera de servicio.",hints:["El bloqueo se aplica sobre el selector del gabinete de control.","Selecciona el Candado y pulsa el punto del control."]},
 {why:"El motor de arranque toma una corriente muy alta de la batería. Abrir el seccionador del circuito de arranque evita arranques por orden eléctrica y chispas al trabajar cerca de los bornes.",risk:"Una herramienta metálica que haga puente entre bornes con el circuito vivo produce arco, quemaduras y daño a la batería.",crit:"Seccionador de arranque abierto. La batería sigue cargada: se aisló el circuito, no se descargó la batería.",learn:"Aislar corta el circuito, pero no elimina la energía almacenada: los bornes de la batería siguen con tensión.",obj:"Abrir el seccionador del circuito de arranque junto a la batería.",hints:["El seccionador está junto a la batería, en el costado del bastidor.","Usa la Mano con guante y pulsa el punto del seccionador."]},
 {why:"El nivel de aceite se lee con el motor detenido y el aceite ya asentado en el cárter. La primera extracción llena la varilla de salpicaduras; solo la segunda lectura, con la varilla limpia y bien asentada, es confiable.",risk:"Poco aceite desgasta los cojinetes hasta gripar el motor; exceso de aceite produce espuma, presión alta y fugas.",crit:"Nivel entre las marcas MIN y MAX, leído con la varilla limpia.",learn:"Se lee entre marcas, con motor detenido y varilla limpia: limpiar, reinsertar completa y leer en la segunda extracción.",obj:"Obtener una lectura confiable del nivel de aceite.",hints:["La varilla de aceite está en el costado del motor, con una argolla amarilla.","Mano para extraer e insertar; Paño para limpiarla. Después ajusta tu lectura en la escala."]},
 {why:"El aire atraviesa las aletas del radiador para disipar el calor del refrigerante. El polvo las tapa y reduce el flujo de aire disponible.",risk:"Con el radiador obstruido el motor se sobrecalienta y puede dispararse por alta temperatura justo cuando se necesita en una emergencia.",crit:"Aletas libres de polvo, sin doblarlas, con el equipo detenido y frío.",learn:"Un radiador limpio es disponibilidad: sin enfriamiento suficiente el grupo se dispara cuando más se le necesita.",obj:"Limpiar las ocho zonas sucias de la cara del radiador.",hints:["El radiador está en el extremo del grupo; el conducto se abrió para que lo veas.","Selecciona el Cepillo y arrastra sobre las zonas marrones."]},
 {why:"El filtro retiene el polvo antes de que entre al motor. Uno saturado restringe el aire; uno dañado o mal asentado deja pasar abrasivos.",risk:"El polvo dentro de los cilindros acelera el desgaste; un filtro tapado causa humo negro y pérdida de potencia.",crit:"Elemento correcto, íntegro y asentado; tapa cerrada y sellada; par de apriete según el manual del equipo.",learn:"Se cambia por la referencia del fabricante, se revisa que asiente sin holgura y se cierra con el par indicado en el manual.",obj:"Sustituir el elemento del filtro de aire y cerrar la tapa.",hints:["La caja del filtro de admisión está en la parte superior del motor.","Primero la Llave de vaso para los dos cierres; luego Mano para la tapa y Filtro nuevo para instalar."]},
 {why:"Los depósitos blancos o verdosos en los bornes pueden elevar la resistencia de contacto. Este escenario solo autoriza observarlos y documentarlos.",risk:"El seccionador de arranque no elimina la energía almacenada de la batería; tocar o cepillar bornes puede causar cortocircuitos.",crit:"Ambos bornes observados, corrosión registrada y correctiva pendiente; sin desmontar ni limpiar conexiones energizadas.",learn:"Encontrar suciedad no significa haberla limpiado. El juego deja anotado que falta ese trabajo.",obj:"Mirar los dos terminales con la linterna; el juego guarda la observación automáticamente.",hints:["Los depósitos blancos están en los dos bornes de la batería.","Toma la Linterna. Observa ambos puntos; la corrosión debe permanecer visible."]},
 {why:"Con la batería en reposo, la tensión indica su estado de carga: alrededor de 12.6 V corresponde a carga completa en una batería de plomo-ácido de 12 V (valores orientativos). Se mide en tensión continua, con la punta roja al positivo y la negra al negativo.",risk:"Una función equivocada del multímetro o puntas en corto producen chispa y daño al instrumento.",crit:"Lectura estable en V DC con la polaridad correcta. La lectura en reposo no prueba la capacidad bajo carga.",learn:"La tensión en reposo indica el estado de carga aproximado; la capacidad de arranque se verifica aparte, bajo carga.",obj:"Medir la tensión de la batería en reposo con la polaridad correcta.",hints:["Mide entre los dos bornes que acabas de limpiar.","Selecciona el Multímetro: punta roja al borne positivo (+) y negra al negativo (−)."]},
 {why:"La unión de protección conecta la carcasa del equipo a tierra para que una falla haga actuar la protección en lugar de energizar la estructura (NOM-001-SEDE, artículo 250).",risk:"Una terminal floja o corroída, o un conductor dañado, puede dejar la carcasa energizada durante una falla.",crit:"Terminal firme, sin corrosión y conductor sin daño visible. La inspección visual no sustituye la medición de continuidad.",learn:"La inspección visual detecta corrosión, daños y terminales flojas; la continuidad solo se demuestra con medición.",obj:"Inspeccionar visualmente los tres puntos de la unión de protección.",hints:["La unión está en la base de la bancada, al frente del equipo.","Selecciona la Linterna y pulsa los tres puntos."]},
 {why:"Cada herramienta o trapo que se queda dentro del equipo es un riesgo: cerca del ventilador, de la admisión o sobre bornes con tensión.",risk:"Un paño olvidado en el ventilador o la admisión, o una llave sobre los bornes, puede causar una falla grave al arrancar.",crit:"Todas las herramientas registradas al inicio salen del equipo y el área queda despejada.",learn:"Antes de cerrar se cuenta todo lo que entró: cero herramientas olvidadas.",obj:"Retirar y guardar el paño y la llave en la bolsa de herramientas.",hints:["El paño y la llave quedaron en el piso, frente al equipo.","Selecciona la Mano con guante y pulsa cada objeto."]},
 {why:"El bloqueo solo se retira cuando el trabajo terminó y el equipo está listo. Lo retira quien lo colocó, después de confirmar que el área está libre y avisar a operación.",risk:"Retirarlo con prisa, o por otra persona, puede energizar el equipo con alguien aún trabajando en él.",crit:"Trabajo cerrado, personas fuera del equipo, herramientas contadas y operación informada.",learn:"El bloqueo lo retira quien lo puso, al final y con aviso: restablecer también es un paso de seguridad.",obj:"Retirar el candado y devolver el control a operación.",hints:["Es el mismo punto de control donde pusiste el candado.","Selecciona el Candado y pulsa el control."]},
 {why:"La prueba funcional demuestra que todo el sistema cumple su propósito: se detecta la falla de red, el grupo arranca, estabiliza tensión y frecuencia, y la carga se transfiere sin disparos.",risk:"Un equipo que no se prueba tras el mantenimiento puede fallar en la emergencia real sin que nadie lo sepa.",crit:"Arranque automático, tensión y frecuencia estables antes de transferir, y transferencia sin disparos.",learn:"Una intervención no termina hasta probar la función completa: la prueba valida el trabajo.",obj:"Provocar una falla de red y observar la secuencia completa.",hints:["El botón para iniciar la prueba está en el cuaderno (Q).","Observa tensión, frecuencia y estado de transferencia durante la prueba."]}
 ];
