 function prepareOrder(){const checks=WorkOrders36.orders[index].checks.map((_,i)=>!!ui.querySelector('input[name="orderCheck"][value="'+i+'"]:checked')),choice=ui.querySelector('input[name="orderDecision"]:checked'),selected=choice?Number(choice.value):null,result=WorkOrders36.validate(index,checks,selected);if(!result.ok){$('orderMessage').textContent=result.message;return false;}Object.assign(orderProgress[index],{ready:true,checks,choice:selected});draw();say(result.message);return true;}
