 (document.querySelector('header .hmi-meta')||document.querySelector('header')).prepend(chip);
 function paint(){const L=lv(xp),lo=150*(L-1)**2,hi=150*L*L;$('hxLv').textContent=L;$('hxRank').textContent=ranks[Math.min(L-1,ranks.length-1)];$('hxFill').style.width=Math.round((xp-lo)/(hi-lo)*100)+'%';$('hxNum').textContent=xp+' XP';$('hudSound').setAttribute('aria-pressed',String(mute));}
